import { MakeLogicType, afterMount, connect, kea, listeners, path } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { projectLogic } from 'scenes/projectLogic'

import { accountRelationshipDefinitionsList } from 'products/customer_analytics/frontend/generated/api'
import type { AccountRelationshipDefinitionApi } from 'products/customer_analytics/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountRelationshipDefinitionsLogicValues {
    currentProjectId: number | null // projectLogic
    definitions: AccountRelationshipDefinitionApi[]
    definitionsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountRelationshipDefinitionsLogicActions {
    loadCurrentProjectSuccess: (
        currentProject: null | import('~/types').ProjectType,
        payload?: any
    ) => {
        currentProject: null | import('~/types').ProjectType
        payload?: any
    } // projectLogic
    loadDefinitions: () => any
    loadDefinitionsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDefinitionsSuccess: (
        definitions: AccountRelationshipDefinitionApi[],
        payload?: any
    ) => {
        definitions: AccountRelationshipDefinitionApi[]
        payload?: any
    }
}

export type accountRelationshipDefinitionsLogicType = MakeLogicType<
    accountRelationshipDefinitionsLogicValues,
    accountRelationshipDefinitionsLogicActions
>

export const accountRelationshipDefinitionsLogic = kea<accountRelationshipDefinitionsLogicType>([
    path([
        'products',
        'workflows',
        'frontend',
        'Workflows',
        'hogflows',
        'registry',
        'triggers',
        'accountRelationshipDefinitionsLogic',
    ]),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
        actions: [projectLogic, ['loadCurrentProjectSuccess']],
    })),
    loaders(({ values }) => ({
        definitions: [
            [] as AccountRelationshipDefinitionApi[],
            {
                loadDefinitions: async (): Promise<AccountRelationshipDefinitionApi[]> => {
                    if (!values.currentProjectId) {
                        return []
                    }
                    try {
                        const response = await accountRelationshipDefinitionsList(String(values.currentProjectId))
                        return response.results
                    } catch (error) {
                        posthog.captureException(error, { scope: 'accountRelationshipDefinitionsLogic.load' })
                        return values.definitions
                    }
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        loadDefinitionsFailure: ({ error }) => {
            posthog.captureException(error, {
                scope: 'accountRelationshipDefinitionsLogic.load',
            })
        },
        // The logic can mount before the project resolves; retry the load once it does.
        loadCurrentProjectSuccess: () => {
            actions.loadDefinitions()
        },
    })),
    afterMount(({ actions }) => {
        actions.loadDefinitions()
    }),
])
